(() => {
  "use strict";

  const IMAGE_DATA = {
    logo: { base64: "", width: 412, height: 420 },
    signature: { base64: "", width: 697, height: 320 },
    stamp: { pngBase64: "", rgbBase64: "", alphaBase64: "", width: 500, height: 477, kind: "png-alpha" }
  };

  const A4_WIDTH = 595.28;
  const A4_HEIGHT = 841.89;
  const encoder = new TextEncoder();

  function bytesFromBase64(value){
    const binary=atob(value);
    const bytes=new Uint8Array(binary.length);
    for(let i=0;i<binary.length;i++) bytes[i]=binary.charCodeAt(i);
    return bytes;
  }

  function joinBytes(parts){
    const total=parts.reduce((sum,part)=>sum+part.length,0);
    const output=new Uint8Array(total);
    let offset=0;
    parts.forEach(part=>{output.set(part,offset);offset+=part.length;});
    return output;
  }

  function ascii(value){
    return String(value??"")
      .normalize("NFKD")
      .replace(/[\u0300-\u036f]/g,"")
      .replace(/[–—]/g,"-")
      .replace(/[‘’]/g,"'")
      .replace(/[“”]/g,'"')
      .replace(/×/g,"x")
      .replace(/•/g,"-")
      .replace(/…/g,"...")
      .replace(/[^\x20-\x7E]/g," ")
      .replace(/\s+/g," ")
      .trim();
  }

  function pdfEscape(value){
    return ascii(value).replace(/\\/g,"\\\\").replace(/\(/g,"\\(").replace(/\)/g,"\\)");
  }

  function rupiah(value){
    const number=Math.round(Number(value)||0);
    return "Rp " + number.toLocaleString("id-ID");
  }

  function dateId(value){
    if(!value) return "-";
    const parts=String(value).slice(0,10).split("-").map(Number);
    if(parts.length!==3 || !parts[0]) return ascii(value);
    const months=["Jan","Feb","Mar","Apr","Mei","Jun","Jul","Agu","Sep","Okt","Nov","Des"];
    return `${String(parts[2]).padStart(2,"0")} ${months[parts[1]-1]||""} ${parts[0]}`;
  }

  function textWidth(text,size,bold=false){
    return ascii(text).length*size*(bold?0.56:0.52);
  }

  function truncate(text,maxWidth,size,bold=false){
    let value=ascii(text);
    if(textWidth(value,size,bold)<=maxWidth) return value;
    while(value.length>2 && textWidth(value+"...",size,bold)>maxWidth) value=value.slice(0,-1);
    return value+"...";
  }

  function wrapText(text,maxWidth,size,bold=false,maxLines=3){
    const words=ascii(text).split(/\s+/).filter(Boolean);
    const lines=[];
    let line="";
    for(const word of words){
      const candidate=line?`${line} ${word}`:word;
      if(textWidth(candidate,size,bold)<=maxWidth){
        line=candidate;
      }else{
        if(line) lines.push(line);
        line=word;
        if(lines.length===maxLines-1) break;
      }
    }
    if(line && lines.length<maxLines) lines.push(line);
    if(words.length && lines.length===maxLines){
      const joined=lines.join(" ");
      if(joined.length<ascii(text).length) lines[maxLines-1]=truncate(lines[maxLines-1]+"...",maxWidth,size,bold);
    }
    return lines.length?lines:[""];
  }

  function buildContent(payload){
    const inv=payload.invoice||{};
    const settings=payload.settings||{};
    const items=[...(inv.invoice_items||[])].sort((a,b)=>(a.sort_order||0)-(b.sort_order||0));
    const commands=[];
    const black=[0.032,0.047,0.059];
    const blue=[0.035,0.376,0.655];
    const cyan=[0.035,0.565,0.765];
    const ink=[0.105,0.145,0.180];
    const muted=[0.43,0.48,0.53];
    const line=[0.85,0.88,0.91];
    const soft=[0.975,0.982,0.988];
    const white=[1,1,1];
    const green=[0.10,0.56,0.33];

    const n=v=>Number(v).toFixed(2).replace(/\.00$/,'');
    const yFromTop=top=>A4_HEIGHT-top;
    const setFill=color=>commands.push(`${color.map(n).join(' ')} rg`);
    const setStroke=color=>commands.push(`${color.map(n).join(' ')} RG`);
    const rect=(x,top,w,h,fillColor=null,strokeColor=null,lineWidth=1)=>{
      if(fillColor) setFill(fillColor);
      if(strokeColor){setStroke(strokeColor);commands.push(`${n(lineWidth)} w`);}
      const op=fillColor&&strokeColor?'B':fillColor?'f':'S';
      commands.push(`${n(x)} ${n(A4_HEIGHT-top-h)} ${n(w)} ${n(h)} re ${op}`);
    };
    const polygon=(points,fillColor=null,strokeColor=null,lineWidth=1)=>{
      if(!points.length) return;
      if(fillColor) setFill(fillColor);
      if(strokeColor){setStroke(strokeColor);commands.push(`${n(lineWidth)} w`);}
      const [first,...rest]=points;
      let path=`${n(first[0])} ${n(yFromTop(first[1]))} m `;
      rest.forEach(point=>{path+=`${n(point[0])} ${n(yFromTop(point[1]))} l `;});
      const op=fillColor&&strokeColor?'b':fillColor?'f':'s';
      commands.push(path+`h ${op}`);
    };
    const lineTo=(x1,top1,x2,top2,color=line,width=1)=>{
      setStroke(color);commands.push(`${n(width)} w ${n(x1)} ${n(yFromTop(top1))} m ${n(x2)} ${n(yFromTop(top2))} l S`);
    };
    const drawText=(value,x,top,size=9,options={})=>{
      const bold=!!options.bold;
      const color=options.color||ink;
      const maxWidth=options.maxWidth||0;
      let text=ascii(value);
      if(maxWidth) text=truncate(text,maxWidth,size,bold);
      let tx=x;
      const width=textWidth(text,size,bold);
      if(options.align==='right') tx=x-width;
      if(options.align==='center') tx=x-width/2;
      setFill(color);
      commands.push(`BT /${bold?'F2':'F1'} ${n(size)} Tf 1 0 0 1 ${n(tx)} ${n(yFromTop(top))} Tm (${pdfEscape(text)}) Tj ET`);
    };
    const drawWrapped=(value,x,top,maxWidth,size=8,lineHeight=11,options={})=>{
      const lines=wrapText(value,maxWidth,size,!!options.bold,options.maxLines||3);
      lines.forEach((text,index)=>drawText(text,x,top+index*lineHeight,size,{...options,maxWidth}));
      return lines.length*lineHeight;
    };
    const drawImage=(name,x,top,w,h)=>{
      commands.push(`q ${n(w)} 0 0 ${n(h)} ${n(x)} ${n(A4_HEIGHT-top-h)} cm /${name} Do Q`);
    };

    // Header with diagonal composition inspired by the supplied reference.
    rect(0,0,A4_WIDTH,136,black);
    polygon([[354,0],[A4_WIDTH,0],[A4_WIDTH,136],[304,136]],blue);
    polygon([[329,0],[350,0],[300,136],[279,136]],cyan);
    lineTo(354,0,304,136,white,1.1);
    lineTo(329,0,279,136,[0.75,0.91,0.98],0.8);

    drawImage('ImLogo',24,20,70,70);
    drawText(settings.store_name||'LORHIL AC',105,48,20,{bold:true,color:white,maxWidth:205});
    drawText('SPESIALIS AIR CONDITIONER',105,67,8.5,{bold:true,color:[0.45,0.79,0.94],maxWidth:205});
    drawText(`WhatsApp ${settings.phone||'081366752281'}`,105,87,7.2,{color:[0.83,0.87,0.90],maxWidth:205});
    drawText(settings.address||'LORHIL AC',105,101,6.8,{color:[0.72,0.78,0.82],maxWidth:205});

    drawText('INVOICE',552,43,25,{bold:true,color:white,align:'right'});
    drawText('Nomor Invoice',392,66,6.8,{color:[0.77,0.89,0.96]});
    drawText(inv.invoice_number||'-',552,66,8.8,{bold:true,color:white,align:'right',maxWidth:150});
    drawText('Tanggal',392,84,6.8,{color:[0.77,0.89,0.96]});
    drawText(`${dateId(inv.work_date)} ${(inv.work_time||'').slice(0,5)}`,552,84,8,{bold:true,color:white,align:'right',maxWidth:150});
    drawText('Status',392,102,6.8,{color:[0.77,0.89,0.96]});
    drawText(inv.status||'-',552,102,8,{bold:true,color:white,align:'right',maxWidth:150});

    // Customer and payment information.
    drawText('INVOICE TO:',32,164,7.4,{bold:true,color:blue});
    drawText(inv.customer_name||'Pelanggan',32,184,13,{bold:true,color:ink,maxWidth:285});
    drawText(`WhatsApp: ${inv.customer_phone||'-'}`,32,202,7.6,{color:muted,maxWidth:285});
    drawWrapped(`Alamat: ${inv.customer_address||'-'}`,32,217,285,7.3,10,{color:muted,maxLines:3});

    drawText('METODE PEMBAYARAN',368,164,7.4,{bold:true,color:blue});
    drawWrapped(settings.payment_info||'Tunai / Transfer',368,184,194,7.2,10,{color:ink,maxLines:5});

    lineTo(32,247,563,247,line,0.8);
    drawText('DETAIL PEKERJAAN',32,268,7.4,{bold:true,color:blue});
    drawText('Rincian jasa dan pekerjaan sesuai pesanan pelanggan.',32,284,7.2,{color:muted,maxWidth:450});

    // Item table.
    const tableX=32, tableW=531, tableTop=298, headerH=28;
    const count=Math.max(1,Math.min(items.length,10));
    const rowH=Math.max(18,Math.min(25,220/count));
    const fontSize=rowH<21?6.8:7.5;
    rect(tableX,tableTop,tableW,headerH,blue);
    polygon([[330,tableTop],[347,tableTop],[330,tableTop+headerH],[313,tableTop+headerH]],cyan);
    polygon([[469,tableTop],[486,tableTop],[469,tableTop+headerH],[452,tableTop+headerH]],cyan);
    drawText('No.',53,317,7.2,{bold:true,color:white,align:'center'});
    drawText('Keterangan Pekerjaan',75,317,7.2,{bold:true,color:white});
    drawText('Harga',416,317,7.2,{bold:true,color:white,align:'right'});
    drawText('Qty',454,317,7.2,{bold:true,color:white,align:'center'});
    drawText('Total',550,317,7.2,{bold:true,color:white,align:'right'});

    let rowTop=tableTop+headerH;
    const visibleItems=items.slice(0,10);
    visibleItems.forEach((item,index)=>{
      if(index%2===1) rect(tableX,rowTop,tableW,rowH,soft);
      lineTo(tableX,rowTop+rowH,tableX+tableW,rowTop+rowH,line,0.55);
      lineTo(68,rowTop,68,rowTop+rowH,line,0.45);
      lineTo(334,rowTop,334,rowTop+rowH,line,0.45);
      lineTo(430,rowTop,430,rowTop+rowH,line,0.45);
      lineTo(478,rowTop,478,rowTop+rowH,line,0.45);
      drawText(String(index+1).padStart(2,'0'),53,rowTop+rowH*0.65,fontSize,{align:'center',color:muted});
      drawText(item.description||'-',78,rowTop+rowH*0.65,fontSize,{bold:true,color:ink,maxWidth:244});
      drawText(rupiah(item.unit_price),418,rowTop+rowH*0.65,fontSize,{align:'right',color:ink,maxWidth:78});
      drawText(String(item.quantity||0),454,rowTop+rowH*0.65,fontSize,{align:'center',color:ink});
      const total=Number(item.line_total ?? ((Number(item.quantity)||0)*(Number(item.unit_price)||0)))||0;
      drawText(rupiah(total),550,rowTop+rowH*0.65,fontSize,{align:'right',bold:true,color:ink,maxWidth:68});
      rowTop+=rowH;
    });
    if(items.length>visibleItems.length){
      drawText(`+ ${items.length-visibleItems.length} pekerjaan lain`,78,rowTop+13,6.8,{color:muted});
      rowTop+=18;
    }
    rect(tableX,tableTop,tableW,rowTop-tableTop,null,line,0.8);

    const lowerTop=Math.max(500,rowTop+18);
    drawText('CATATAN & KETENTUAN',32,lowerTop+10,7.4,{bold:true,color:blue});
    drawWrapped(inv.notes||settings.footer_note||'Terima kasih telah menggunakan layanan LORHIL AC.',32,lowerTop+29,315,7.1,10,{color:muted,maxLines:5});
    drawText('Pembayaran:',32,lowerTop+87,7.1,{bold:true,color:ink});
    drawWrapped(settings.payment_info||'Tunai / Transfer',94,lowerTop+87,250,7.1,9.5,{color:muted,maxLines:3});

    const totalX=379,totalW=184;
    const rows=[
      ['Subtotal',inv.subtotal],
      ['Diskon',inv.discount],
      ['Dibayar',inv.paid],
      ['Sisa',inv.balance]
    ];
    rows.forEach((entry,index)=>{
      const top=lowerTop+8+index*20;
      drawText(entry[0],totalX,top,7.4,{color:muted});
      drawText(rupiah(entry[1]),563,top,7.6,{bold:true,color:ink,align:'right',maxWidth:105});
    });
    polygon([[398,lowerTop+91],[563,lowerTop+91],[563,lowerTop+121],[379,lowerTop+121]],blue);
    drawText('TOTAL',413,lowerTop+111,9,{bold:true,color:white});
    drawText(rupiah(inv.total),552,lowerTop+111,10,{bold:true,color:white,align:'right',maxWidth:112});

    const signTop=Math.min(714,Math.max(680,lowerTop+128));
    drawText('Terima kasih telah menggunakan',32,signTop+12,8,{color:muted});
    drawText(settings.store_name||'LORHIL AC',32,signTop+30,15,{bold:true,color:blue,maxWidth:250});
    drawText('Kami menghargai kepercayaan Anda.',32,signTop+47,7.3,{color:muted,maxWidth:250});

    drawText('Hormat kami,',457,signTop,7.4,{color:muted,align:'center'});
    drawImage('ImSignature',398,signTop+8,112,45);
    drawImage('ImStamp',478,signTop+2,60,57);
    lineTo(391,signTop+62,548,signTop+62,line,0.8);
    drawText(settings.signer_name||'Hendri Nova Lismana',469.5,signTop+77,8.3,{bold:true,color:ink,align:'center',maxWidth:155});
    drawText(settings.signer_role||'Pemilik LORHIL AC',469.5,signTop+91,6.8,{color:muted,align:'center',maxWidth:155});

    // Footer diagonal band.
    rect(0,817,A4_WIDTH,25,blue);
    polygon([[0,817],[352,817],[372,842],[0,842]],black);
    drawText(`WhatsApp: ${settings.phone||'081366752281'}`,32,834,7.2,{color:white});
    drawText('LORHIL AC • Spesialis Air Conditioner',563,834,7.2,{color:white,align:'right'});

    return commands.join('\n');
  }

  function createPdfBytes(payload){
    const contentBytes=encoder.encode(buildContent(payload));
    const images={
      7:{name:"ImLogo",...IMAGE_DATA.logo},
      8:{name:"ImSignature",...IMAGE_DATA.signature}
    };
    const parts=[];
    const offsets=[0];
    let length=0;
    const add=part=>{
      const bytes=typeof part==="string"?encoder.encode(part):part;
      parts.push(bytes);length+=bytes.length;
    };
    const object=(number,body)=>{
      offsets[number]=length;
      add(`${number} 0 obj\n${body}\nendobj\n`);
    };
    const streamObject=(number,dictionary,streamBytes)=>{
      offsets[number]=length;
      add(`${number} 0 obj\n<< ${dictionary} /Length ${streamBytes.length} >>\nstream\n`);
      add(streamBytes);
      add("\nendstream\nendobj\n");
    };

    add("%PDF-1.4\n%LORHIL\n");
    object(1,"<< /Type /Catalog /Pages 2 0 R >>");
    object(2,"<< /Type /Pages /Kids [3 0 R] /Count 1 >>");
    object(3,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${A4_WIDTH} ${A4_HEIGHT}] /Resources << /Font << /F1 5 0 R /F2 6 0 R >> /XObject << /ImLogo 7 0 R /ImSignature 8 0 R /ImStamp 9 0 R >> >> /Contents 4 0 R >>`);
    streamObject(4,"",contentBytes);
    object(5,"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>");
    object(6,"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>");

    Object.entries(images).forEach(([number,image])=>{
      const data=bytesFromBase64(image.base64);
      streamObject(Number(number),`/Type /XObject /Subtype /Image /Width ${image.width} /Height ${image.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode`,data);
    });

    const stamp=IMAGE_DATA.stamp;
    const stampRgb=bytesFromBase64(stamp.rgbBase64);
    const stampAlpha=bytesFromBase64(stamp.alphaBase64);
    streamObject(9,`/Type /XObject /Subtype /Image /Width ${stamp.width} /Height ${stamp.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /FlateDecode /SMask 10 0 R`,stampRgb);
    streamObject(10,`/Type /XObject /Subtype /Image /Width ${stamp.width} /Height ${stamp.height} /ColorSpace /DeviceGray /BitsPerComponent 8 /Filter /FlateDecode`,stampAlpha);

    const xrefOffset=length;
    add(`xref\n0 11\n0000000000 65535 f \n`);
    for(let i=1;i<=10;i++) add(`${String(offsets[i]).padStart(10,"0")} 00000 n \n`);
    add(`trailer\n<< /Size 11 /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF\n`);
    return joinBytes(parts);
  }

  function createPdfBlob(payload){
    return new Blob([createPdfBytes(payload)],{type:"application/pdf"});
  }

  function filename(payload){
    return String(payload.filename||"nota-lorhil-ac.pdf").replace(/[^a-zA-Z0-9._-]+/g,"-");
  }

  function triggerDownload(blob,name){
    const url=URL.createObjectURL(blob);
    const isiOS=/iPad|iPhone|iPod/.test(navigator.userAgent);
    if(isiOS){
      const opened=window.open(url,"_blank");
      if(!opened) window.location.href=url;
    }else{
      const link=document.createElement("a");
      link.href=url;
      link.download=name;
      link.rel="noopener";
      link.style.display="none";
      document.body.appendChild(link);
      link.click();
      link.remove();
    }
    setTimeout(()=>URL.revokeObjectURL(url),180000);
  }

  function whatsappUrl(payload){
    const phone=String(payload.phone||"").replace(/\D/g,"");
    const message=String(payload.message||"");
    return `https://wa.me/${phone}?text=${encodeURIComponent(message)}`;
  }

  function showStatus(message){
    let box=document.getElementById("lorhilInvoiceStatus");
    if(!box){
      box=document.createElement("div");
      box.id="lorhilInvoiceStatus";
      box.style.cssText="position:fixed;left:50%;bottom:24px;transform:translateX(-50%);z-index:100000;background:#0f3442;color:#fff;padding:12px 16px;border-radius:10px;box-shadow:0 8px 24px rgba(0,0,0,.25);font:600 14px Arial;max-width:90%;text-align:center";
      document.body.appendChild(box);
    }
    box.textContent=message;
    box.style.display="block";
    clearTimeout(showStatus.timer);
    showStatus.timer=setTimeout(()=>{box.style.display="none";},3500);
  }

  function downloadPdf(payload){
    try{
      showStatus("Membuat PDF...");
      const blob=createPdfBlob(payload);
      triggerDownload(blob,filename(payload));
      showStatus("PDF berhasil dibuat. Periksa folder Download.");
      return true;
    }catch(error){
      console.error("Gagal membuat PDF",error);
      alert("PDF belum berhasil dibuat: "+(error?.message||error));
      return false;
    }
  }

  function downloadPdfAndOpenWhatsApp(payload){
    const phone=String(payload.phone||"").replace(/\D/g,"");
    if(phone.length<10){
      alert("Nomor WhatsApp pelanggan pada nota belum valid.");
      return false;
    }
    try{
      showStatus("Membuat dan mengunduh PDF...");
      const blob=createPdfBlob(payload);
      triggerDownload(blob,filename(payload));
      showStatus("PDF diunduh. Membuka WhatsApp pelanggan...");
      setTimeout(()=>{window.location.href=whatsappUrl(payload);},700);
      return true;
    }catch(error){
      console.error("Gagal mengunduh PDF dan membuka WhatsApp",error);
      alert("Proses belum berhasil: "+(error?.message||error));
      return false;
    }
  }

  function htmlEscape(value){
    return String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[char]));
  }

  function imageDataUri(image){
    if(image.pngBase64) return `data:image/png;base64,${image.pngBase64}`;
    return `data:image/jpeg;base64,${image.base64}`;
  }

  function buildPrintHtml(payload){
    const inv=payload.invoice||{};
    const s=payload.settings||{};
    const items=[...(inv.invoice_items||[])].sort((a,b)=>(a.sort_order||0)-(b.sort_order||0));
    const visibleItems=items.slice(0,10);
    let rows=visibleItems.map((item,index)=>{
      const total=item.line_total ?? ((Number(item.quantity)||0)*(Number(item.unit_price)||0));
      return `<tr><td>${String(index+1).padStart(2,'0')}</td><td><strong>${htmlEscape(item.description||'-')}</strong></td><td>${htmlEscape(rupiah(item.unit_price))}</td><td>${htmlEscape(item.quantity||0)}</td><td><strong>${htmlEscape(rupiah(total))}</strong></td></tr>`;
    }).join('');
    if(items.length>visibleItems.length){
      rows+=`<tr><td></td><td colspan="4">+ ${items.length-visibleItems.length} pekerjaan lain</td></tr>`;
    }
    return `<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
      @page{size:A4;margin:0}
      *{box-sizing:border-box}
      html,body{margin:0;background:#e8eef1;font-family:Arial,Helvetica,sans-serif;color:#1b2730;-webkit-print-color-adjust:exact;print-color-adjust:exact}
      .sheet{width:210mm;min-height:297mm;margin:0 auto;background:#fff;position:relative;overflow:hidden;padding-bottom:15mm}
      .hero{height:48mm;background:#080c0f;position:relative;color:#fff;overflow:hidden}
      .hero:after{content:"";position:absolute;top:0;right:-17mm;width:108mm;height:100%;background:#0960a7;transform:skewX(-21deg);transform-origin:top}
      .hero:before{content:"";position:absolute;top:0;right:97mm;width:5mm;height:100%;background:#0990c3;transform:skewX(-21deg);z-index:2;border-left:.5mm solid rgba(255,255,255,.8)}
      .brand{position:absolute;left:8mm;top:6mm;z-index:3;display:flex;align-items:center;gap:4mm;width:102mm}
      .brand img{width:25mm;height:25mm;object-fit:contain}
      .brand h1{font-size:20pt;margin:0;line-height:1;color:#fff;letter-spacing:.3px}
      .brand b{display:block;color:#75c9ed;font-size:7.5pt;margin-top:1.5mm}
      .brand p{font-size:6.5pt;line-height:1.45;color:#cbd4d9;margin:2.4mm 0 0}
      .invoice-head{position:absolute;z-index:4;right:8mm;top:7mm;width:62mm;text-align:right}
      .invoice-head h2{font-size:25pt;margin:0 0 3mm;letter-spacing:.5px}
      .invoice-meta{display:grid;grid-template-columns:25mm 1fr;gap:1.4mm 2mm;font-size:6.7pt;text-align:left}
      .invoice-meta strong{text-align:right;color:#fff}
      .status{display:inline;color:#fff;background:transparent;padding:0;border-radius:0;font-style:normal}
      .main{padding:8mm 8mm 0}
      .party{display:grid;grid-template-columns:1.45fr .9fr;gap:10mm;min-height:35mm}
      .eyebrow{font-size:7pt;font-weight:700;color:#0960a7;letter-spacing:.2px;margin-bottom:3mm}
      .customer h3{font-size:13pt;margin:0 0 2mm}
      .customer p,.payment p{font-size:7pt;line-height:1.55;color:#65727b;margin:0;white-space:pre-line}
      .rule{height:.3mm;background:#dfe5e8;margin:4mm 0}
      .detail-title{font-size:7pt;font-weight:700;color:#0960a7;margin-bottom:1.5mm}
      .detail-copy{font-size:7pt;color:#65727b;margin:0 0 4mm}
      .table-wrap{border:1px solid #dce3e7;overflow:hidden}
      table{width:100%;border-collapse:collapse;table-layout:fixed}
      thead{background:#0960a7;color:#fff}
      th{padding:3mm 2.2mm;font-size:7pt;text-align:left;position:relative}
      th:nth-child(1){width:12mm;text-align:center}
      th:nth-child(3){width:34mm;text-align:right}
      th:nth-child(4){width:18mm;text-align:center}
      th:nth-child(5){width:35mm;text-align:right}
      th:nth-child(3):before,th:nth-child(5):before{content:"";position:absolute;left:-4mm;top:0;border-top:9mm solid #0790c3;border-left:4mm solid transparent}
      td{padding:3mm 2.2mm;border-bottom:1px solid #e5eaed;font-size:7pt;vertical-align:top}
      tbody tr:nth-child(even){background:#fafcfd}
      td:nth-child(1),td:nth-child(4){text-align:center;color:#6a7680}
      td:nth-child(3),td:nth-child(5){text-align:right}
      .lower{display:grid;grid-template-columns:1.55fr .9fr;gap:10mm;margin-top:6mm}
      .terms h4{font-size:7pt;color:#0960a7;margin:0 0 2.5mm}
      .terms p{font-size:6.8pt;color:#65727b;line-height:1.55;margin:0 0 3mm;white-space:pre-line}
      .totals{font-size:7.2pt}
      .total-row{display:flex;justify-content:space-between;padding:1.7mm 0;border-bottom:1px solid #edf0f2}
      .total-row span{color:#65727b}.total-row strong{color:#1b2730}
      .grand{margin-top:2.5mm;background:#0960a7;color:#fff;display:flex;justify-content:space-between;align-items:center;padding:3mm 4mm;position:relative;font-size:10pt}
      .grand:before{content:"";position:absolute;left:-7mm;top:0;border-bottom:11mm solid #0960a7;border-left:7mm solid transparent}
      .grand span,.grand strong{color:#fff}
      .closing{display:grid;grid-template-columns:1fr 58mm;gap:12mm;align-items:end;margin-top:10mm;min-height:46mm}
      .thanks p{font-size:7pt;color:#65727b;margin:0 0 2mm}.thanks strong{font-size:15pt;color:#0960a7}
      .signature{text-align:center;position:relative;font-size:7pt;color:#65727b;min-height:43mm}
      .signature .sig{width:40mm;height:17mm;object-fit:contain;margin-top:1mm}
      .signature .stamp{position:absolute;width:22mm;height:22mm;object-fit:contain;right:2mm;top:5mm;background:transparent}
      .signature .line{border-top:1px solid #d5dde1;margin:1mm auto 2mm;width:48mm}
      .signature b{display:block;color:#1b2730;font-size:8pt}
      .footer{position:absolute;bottom:0;left:0;right:0;height:9mm;background:#0960a7;color:#fff;display:flex;justify-content:space-between;align-items:center;padding:0 8mm;font-size:6.5pt}
      .footer:before{content:"";position:absolute;left:0;top:0;width:128mm;height:100%;background:#080c0f;clip-path:polygon(0 0,93% 0,100% 100%,0 100%)}
      .footer span{position:relative;z-index:2}
      @media(max-width:800px){.sheet{width:210mm;transform-origin:top left}}
      @media print{html,body{background:#fff}.sheet{margin:0}}
    </style></head><body><article class="sheet">
      <header class="hero">
        <section class="brand"><img src="${imageDataUri(IMAGE_DATA.logo)}"><div><h1>${htmlEscape(s.store_name||'LORHIL AC')}</h1><b>SPESIALIS AIR CONDITIONER</b><p>WhatsApp ${htmlEscape(s.phone||'081366752281')}<br>${htmlEscape(s.address||'LORHIL AC')}</p></div></section>
        <section class="invoice-head"><h2>INVOICE</h2><div class="invoice-meta"><span>Nomor Invoice</span><strong>${htmlEscape(inv.invoice_number||'-')}</strong><span>Tanggal</span><strong>${htmlEscape(dateId(inv.work_date))} ${htmlEscape((inv.work_time||'').slice(0,5))}</strong><span>Status</span><strong><em class="status">${htmlEscape(inv.status||'-')}</em></strong></div></section>
      </header>
      <main class="main">
        <section class="party"><div class="customer"><div class="eyebrow">INVOICE TO:</div><h3>${htmlEscape(inv.customer_name||'Pelanggan')}</h3><p>WhatsApp: ${htmlEscape(inv.customer_phone||'-')}<br>Alamat: ${htmlEscape(inv.customer_address||'-')}</p></div><div class="payment"><div class="eyebrow">METODE PEMBAYARAN</div><p>${htmlEscape(s.payment_info||'Tunai / Transfer')}</p></div></section>
        <div class="rule"></div><div class="detail-title">DETAIL PEKERJAAN</div><p class="detail-copy">Rincian jasa dan pekerjaan sesuai pesanan pelanggan.</p>
        <section class="table-wrap"><table><thead><tr><th>No.</th><th>Keterangan Pekerjaan</th><th>Harga</th><th>Qty</th><th>Total</th></tr></thead><tbody>${rows||'<tr><td>01</td><td>-</td><td>Rp 0</td><td>0</td><td>Rp 0</td></tr>'}</tbody></table></section>
        <section class="lower"><div class="terms"><h4>CATATAN & KETENTUAN</h4><p>${htmlEscape(inv.notes||s.footer_note||'Terima kasih telah menggunakan layanan LORHIL AC.')}</p><p><b>Pembayaran:</b><br>${htmlEscape(s.payment_info||'Tunai / Transfer')}</p></div><div class="totals"><div class="total-row"><span>Subtotal</span><strong>${htmlEscape(rupiah(inv.subtotal))}</strong></div><div class="total-row"><span>Diskon</span><strong>${htmlEscape(rupiah(inv.discount))}</strong></div><div class="total-row"><span>Dibayar</span><strong>${htmlEscape(rupiah(inv.paid))}</strong></div><div class="total-row"><span>Sisa</span><strong>${htmlEscape(rupiah(inv.balance))}</strong></div><div class="grand"><span>Total</span><strong>${htmlEscape(rupiah(inv.total))}</strong></div></div></section>
        <section class="closing"><div class="thanks"><p>Terima kasih telah menggunakan</p><strong>${htmlEscape(s.store_name||'LORHIL AC')}</strong><p>Kami menghargai kepercayaan Anda.</p></div><div class="signature">Hormat kami,<br><img class="sig" src="${imageDataUri(IMAGE_DATA.signature)}"><img class="stamp" src="${imageDataUri(IMAGE_DATA.stamp)}"><div class="line"></div><b>${htmlEscape(s.signer_name||'Hendri Nova Lismana')}</b><small>${htmlEscape(s.signer_role||'Pemilik LORHIL AC')}</small></div></section>
      </main>
      <footer class="footer"><span>WhatsApp: ${htmlEscape(s.phone||'081366752281')}</span><span>LORHIL AC • Spesialis Air Conditioner</span></footer>
    </article></body></html>`;
  }

  function closePrintPreview(){
    document.getElementById("lorhilPrintOverlay")?.remove();
  }

  function openPrintPreview(payload){
    closePrintPreview();
    const overlay=document.createElement("div");
    overlay.id="lorhilPrintOverlay";
    overlay.style.cssText="position:fixed;inset:0;z-index:99999;background:#dfe8ec;display:flex;flex-direction:column";
    const bar=document.createElement("div");
    bar.style.cssText="display:flex;gap:8px;flex-wrap:wrap;padding:10px;background:#fff;box-shadow:0 2px 10px rgba(0,0,0,.15);z-index:2";
    const button=(label,style,handler)=>{
      const btn=document.createElement("button");
      btn.type="button";btn.textContent=label;btn.style.cssText=`border:0;border-radius:9px;padding:11px 13px;color:#fff;font-weight:700;background:${style};cursor:pointer`;
      btn.addEventListener("click",handler);return btn;
    };
    const frame=document.createElement("iframe");
    frame.title="Preview Nota";
    frame.style.cssText="flex:1;width:100%;border:0;background:#eef3f5";
    frame.srcdoc=buildPrintHtml(payload);
    bar.appendChild(button("Cetak Sekarang","#0f3442",()=>{
      try{frame.contentWindow.focus();frame.contentWindow.print();}
      catch(error){console.error(error);alert("Dialog cetak tidak dapat dibuka. Gunakan tombol Download PDF.");}
    }));
    bar.appendChild(button("Download PDF","#1384b5",()=>downloadPdf(payload)));
    bar.appendChild(button("Download PDF & Buka WhatsApp","#1f8f5f",()=>downloadPdfAndOpenWhatsApp(payload)));
    bar.appendChild(button("Tutup","#6b7f88",closePrintPreview));
    overlay.appendChild(bar);overlay.appendChild(frame);document.body.appendChild(overlay);
    document.body.style.overflow="hidden";
    const observer=new MutationObserver(()=>{
      if(!document.body.contains(overlay)){document.body.style.overflow="";observer.disconnect();}
    });
    observer.observe(document.body,{childList:true});
    return true;
  }

  window.LorhilInvoiceEngine={
    createPdfBytes,
    createPdfBlob,
    downloadPdf,
    downloadPdfAndOpenWhatsApp,
    openPrintPreview,
    closePrintPreview,
    buildPrintHtml
  };
})();
